import { describe, it, expect, beforeEach, vi } from 'vitest';
import {
  bytesToBase64Url,
  computeEmployeeUserHandle,
  derEcdsaToP1363,
  hasActiveBiometricForUser,
  verifyWebAuthnAssertionCryptographically,
} from '../webAuthnBiometricService';
import { authService, saveCustomEmployeePassword } from '../authService';

/**
 * Converts a raw 64-byte IEEE P1363 ECDSA signature (`r || s`) generated by WebCrypto
 * into ASN.1 DER (`SEQUENCE { INTEGER r, INTEGER s }`), matching real hardware authenticators.
 */
function p1363ToDerEcdsa(rawSig: Uint8Array): Uint8Array {
  const encodeInt = (slice: Uint8Array): Uint8Array => {
    let start = 0;
    while (start < slice.length - 1 && slice[start] === 0) {
      start++;
    }
    const trimmed = slice.slice(start);
    const needsLeadingZero = (trimmed[0] & 0x80) !== 0;
    const out = new Uint8Array(2 + (needsLeadingZero ? 1 : 0) + trimmed.length);
    out[0] = 0x02;
    out[1] = trimmed.length + (needsLeadingZero ? 1 : 0);
    if (needsLeadingZero) {
      out[2] = 0x00;
      out.set(trimmed, 3);
    } else {
      out.set(trimmed, 2);
    }
    return out;
  };

  const rDer = encodeInt(rawSig.slice(0, 32));
  const sDer = encodeInt(rawSig.slice(32, 64));
  const seq = new Uint8Array(2 + rDer.length + sDer.length);
  seq[0] = 0x30;
  seq[1] = rDer.length + sDer.length;
  seq.set(rDer, 2);
  seq.set(sDer, 2 + rDer.length);
  return seq;
}

async function buildAuthenticatorData(
  rpId: string,
  flags: number,
  signCount: number
): Promise<Uint8Array> {
  const rpIdHash = new Uint8Array(
    await crypto.subtle.digest('SHA-256', new TextEncoder().encode(rpId))
  );
  const authData = new Uint8Array(37);
  authData.set(rpIdHash, 0);
  authData[32] = flags;
  const view = new DataView(authData.buffer);
  view.setUint32(33, signCount, false);
  return authData;
}

interface SimulatedHardwarePasskey {
  email: string;
  rawId: Uint8Array;
  credentialIdB64Url: string;
  keyPair: CryptoKeyPair;
  spkiBuffer: ArrayBuffer;
  userHandle: Uint8Array;
  signCount: number;
}

async function createHardwarePasskeyFixture(email: string): Promise<SimulatedHardwarePasskey> {
  const keyPair = await crypto.subtle.generateKey(
    { name: 'ECDSA', namedCurve: 'P-256' },
    true,
    ['sign', 'verify']
  );
  const spkiBuffer = await crypto.subtle.exportKey('spki', keyPair.publicKey);
  const rawId = crypto.getRandomValues(new Uint8Array(32));
  const userHandle = await computeEmployeeUserHandle(email);
  return {
    email,
    rawId,
    credentialIdB64Url: bytesToBase64Url(rawId),
    keyPair,
    spkiBuffer,
    userHandle,
    signCount: 1,
  };
}

describe('Real WebAuthn / FIDO2 Per-Employee Cryptographic Biometric Auth', () => {
  const rpId = window.location.hostname || 'localhost';
  const origin = window.location.origin;
  const khalidEmail = 'khalid@kas.sa';
  const otherEmployeeEmail = 'a.salif.dev@kas.sa';
  const testKhalidPass = 'K@s#Auth_99281!Zx';
  const testOtherPass = 'D3v#Auth_77412!Qp';

  let createSpy: ReturnType<typeof vi.fn>;
  let getSpy: ReturnType<typeof vi.fn>;

  beforeEach(() => {
    localStorage.clear();
    sessionStorage.clear();
    saveCustomEmployeePassword(khalidEmail, testKhalidPass);
    saveCustomEmployeePassword(otherEmployeeEmail, testOtherPass);

    createSpy = vi.fn();
    getSpy = vi.fn();

    Object.defineProperty(window, 'PublicKeyCredential', {
      configurable: true,
      writable: true,
      value: {
        isUserVerifyingPlatformAuthenticatorAvailable: vi.fn().mockResolvedValue(true),
      },
    });

    Object.defineProperty(navigator, 'credentials', {
      configurable: true,
      writable: true,
      value: {
        create: createSpy,
        get: getSpy,
      },
    });
  });

  it('round-trips ASN.1 DER ECDSA signatures to raw 64-byte P1363 accurately', () => {
    const sampleP1363 = new Uint8Array(64);
    sampleP1363[0] = 0x8f; // high bit set -> tests leading 0x00 integer padding in DER
    sampleP1363[31] = 0x42;
    sampleP1363[32] = 0x00; // leading zero in s
    sampleP1363[33] = 0x7a;
    sampleP1363[63] = 0x19;

    const der = p1363ToDerEcdsa(sampleP1363);
    expect(der[0]).toBe(0x30);
    const decoded = derEcdsaToP1363(der, 32);
    expect(Array.from(decoded)).toEqual(Array.from(sampleP1363));
  });

  it('NEVER auto-enrolls or logs in an un-enrolled employee during signInWithBiometric', async () => {
    const res = await authService.signInWithBiometric(khalidEmail);
    expect(res.data).toBeNull();
    expect(res.notEnrolled).toBe(true);
    expect(res.error?.message).toContain(khalidEmail);
    expect(createSpy).not.toHaveBeenCalled();
    expect(getSpy).not.toHaveBeenCalled();
  });

  it('blocks biometric enrollment with an invalid password or excluded/unauthorized email', async () => {
    const wrongPassRes = await authService.enrollAuthorizedBiometricWithPassword(
      khalidEmail,
      'WrongPass!123456'
    );
    expect(wrongPassRes.data).toBeNull();
    expect(wrongPassRes.error?.message).toContain('رفض أمني');
    expect(createSpy).not.toHaveBeenCalled();

    const excludedRes = await authService.enrollAuthorizedBiometricWithPassword(
      'o.saeed.hospitality@kas.sa',
      testKhalidPass
    );
    expect(excludedRes.data).toBeNull();
    expect(createSpy).not.toHaveBeenCalled();

    const outsiderRes = await authService.signInWithBiometric('hacker@external-domain.com');
    expect(outsiderRes.data).toBeNull();
    expect(getSpy).not.toHaveBeenCalled();
  });

  it('enrolls an authorized employee passkey after password verification and authenticates ONLY with matching ECDSA signature', async () => {
    const khalidKey = await createHardwarePasskeyFixture(khalidEmail);

    createSpy.mockImplementationOnce(async (opts: CredentialCreationOptions) => {
      const pubOpts = opts.publicKey!;
      const authData = await buildAuthenticatorData(rpId, 0x01 | 0x04 | 0x40, 1);
      const clientDataJSON = new TextEncoder().encode(
        JSON.stringify({
          type: 'webauthn.create',
          challenge: bytesToBase64Url(pubOpts.challenge as ArrayBuffer),
          origin,
        })
      );
      return {
        id: khalidKey.credentialIdB64Url,
        rawId: khalidKey.rawId.buffer,
        type: 'public-key',
        response: {
          clientDataJSON: clientDataJSON.buffer,
          attestationObject: new ArrayBuffer(0),
          getPublicKey: () => khalidKey.spkiBuffer,
          getPublicKeyAlgorithm: () => -7,
          getAuthenticatorData: () => authData.buffer,
        },
      };
    });

    const enrollRes = await authService.enrollAuthorizedBiometricWithPassword(
      khalidEmail,
      testKhalidPass,
      'Touch ID (بصمة إصبع)'
    );
    expect(enrollRes.error).toBeNull();
    expect(enrollRes.data?.email).toBe(khalidEmail);
    expect(enrollRes.data?.authenticated_via).toBe('webauthn_biometric');

    const status = await hasActiveBiometricForUser(khalidEmail);
    expect(status.enrolled).toBe(true);
    expect(status.count).toBe(1);

    // Now perform real cryptographic login with khalid's hardware private key (UV=1, signCount=2)
    getSpy.mockImplementationOnce(async (opts: CredentialRequestOptions) => {
      const pubOpts = opts.publicKey!;
      // Verify allowCredentials strictly scopes to khalid's enrolled credential ONLY
      expect(pubOpts.userVerification).toBe('required');
      expect(pubOpts.allowCredentials).toHaveLength(1);

      const authData = await buildAuthenticatorData(rpId, 0x01 | 0x04, 2);
      const clientDataJSON = new TextEncoder().encode(
        JSON.stringify({
          type: 'webauthn.get',
          challenge: bytesToBase64Url(pubOpts.challenge as ArrayBuffer),
          origin,
        })
      );
      const clientHash = new Uint8Array(await crypto.subtle.digest('SHA-256', clientDataJSON));
      const payload = new Uint8Array(authData.length + clientHash.length);
      payload.set(authData, 0);
      payload.set(clientHash, authData.length);

      const rawP1363Sig = new Uint8Array(
        await crypto.subtle.sign(
          { name: 'ECDSA', hash: 'SHA-256' },
          khalidKey.keyPair.privateKey,
          payload
        )
      );
      const derSig = p1363ToDerEcdsa(rawP1363Sig);

      return {
        id: khalidKey.credentialIdB64Url,
        rawId: khalidKey.rawId.buffer,
        type: 'public-key',
        response: {
          authenticatorData: authData.buffer,
          clientDataJSON: clientDataJSON.buffer,
          signature: derSig.buffer,
          userHandle: khalidKey.userHandle.buffer,
        },
      };
    });

    const loginRes = await authService.signInWithBiometric(khalidEmail);
    expect(loginRes.error).toBeNull();
    expect(loginRes.data?.email).toBe(khalidEmail);
    expect(loginRes.data?.authenticated_via).toBe('webauthn_biometric');
    expect(loginRes.credentialId).toBe(khalidKey.credentialIdB64Url);
  });

  it('strictly rejects cross-employee biometric spoofing, forged signatures, UV=0, and cloned sign counters', async () => {
    const khalidKey = await createHardwarePasskeyFixture(khalidEmail);
    const otherEmpKey = await createHardwarePasskeyFixture(otherEmployeeEmail);

    // Enroll both employees legitimately with their respective passwords & hardware keys
    for (const [empEmail, empPass, fixture] of [
      [khalidEmail, testKhalidPass, khalidKey],
      [otherEmployeeEmail, testOtherPass, otherEmpKey],
    ] as const) {
      createSpy.mockImplementationOnce(async (opts: CredentialCreationOptions) => {
        const authData = await buildAuthenticatorData(rpId, 0x01 | 0x04, 5);
        const clientDataJSON = new TextEncoder().encode(
          JSON.stringify({
            type: 'webauthn.create',
            challenge: bytesToBase64Url(opts.publicKey!.challenge as ArrayBuffer),
            origin,
          })
        );
        return {
          id: fixture.credentialIdB64Url,
          rawId: fixture.rawId.buffer,
          type: 'public-key',
          response: {
            clientDataJSON: clientDataJSON.buffer,
            attestationObject: new ArrayBuffer(0),
            getPublicKey: () => fixture.spkiBuffer,
            getPublicKeyAlgorithm: () => -7,
            getAuthenticatorData: () => authData.buffer,
          },
        };
      });
      const res = await authService.enrollAuthorizedBiometricWithPassword(empEmail, empPass);
      expect(res.error).toBeNull();
    }

    // Attack 1: Second employee presents THEIR enrolled biometric credential while trying to log into khalid@kas.sa
    getSpy.mockImplementationOnce(async (opts: CredentialRequestOptions) => {
      const authData = await buildAuthenticatorData(rpId, 0x01 | 0x04, 6);
      const clientDataJSON = new TextEncoder().encode(
        JSON.stringify({
          type: 'webauthn.get',
          challenge: bytesToBase64Url(opts.publicKey!.challenge as ArrayBuffer),
          origin,
        })
      );
      const clientHash = new Uint8Array(await crypto.subtle.digest('SHA-256', clientDataJSON));
      const payload = new Uint8Array(authData.length + clientHash.length);
      payload.set(authData, 0);
      payload.set(clientHash, authData.length);
      const sig = p1363ToDerEcdsa(
        new Uint8Array(
          await crypto.subtle.sign(
            { name: 'ECDSA', hash: 'SHA-256' },
            otherEmpKey.keyPair.privateKey,
            payload
          )
        )
      );
      return {
        id: otherEmpKey.credentialIdB64Url,
        rawId: otherEmpKey.rawId.buffer,
        type: 'public-key',
        response: {
          authenticatorData: authData.buffer,
          clientDataJSON: clientDataJSON.buffer,
          signature: sig.buffer,
          userHandle: otherEmpKey.userHandle.buffer,
        },
      };
    });

    const crossUserAttack = await authService.signInWithBiometric(khalidEmail);
    expect(crossUserAttack.data).toBeNull();
    expect(crossUserAttack.error?.message).toContain('تخص موظفاً آخر');

    // Attack 2: Spoofed credentialId claiming to be khalid@kas.sa, but signed by otherEmpKey's private key
    getSpy.mockImplementationOnce(async (opts: CredentialRequestOptions) => {
      const authData = await buildAuthenticatorData(rpId, 0x01 | 0x04, 6);
      const clientDataJSON = new TextEncoder().encode(
        JSON.stringify({
          type: 'webauthn.get',
          challenge: bytesToBase64Url(opts.publicKey!.challenge as ArrayBuffer),
          origin,
        })
      );
      const clientHash = new Uint8Array(await crypto.subtle.digest('SHA-256', clientDataJSON));
      const payload = new Uint8Array(authData.length + clientHash.length);
      payload.set(authData, 0);
      payload.set(clientHash, authData.length);
      const wrongKeySig = p1363ToDerEcdsa(
        new Uint8Array(
          await crypto.subtle.sign(
            { name: 'ECDSA', hash: 'SHA-256' },
            otherEmpKey.keyPair.privateKey,
            payload
          )
        )
      );
      return {
        id: khalidKey.credentialIdB64Url,
        rawId: khalidKey.rawId.buffer,
        type: 'public-key',
        response: {
          authenticatorData: authData.buffer,
          clientDataJSON: clientDataJSON.buffer,
          signature: wrongKeySig.buffer,
          userHandle: khalidKey.userHandle.buffer,
        },
      };
    });

    const wrongSignatureAttack = await authService.signInWithBiometric(khalidEmail);
    expect(wrongSignatureAttack.data).toBeNull();
    expect(wrongSignatureAttack.error?.message).toContain('غير مطابق للمفتاح العام');

    // Attack 3: Presence-only assertion without real biometric verification (UV=0, flags=0x01)
    const challenge = crypto.getRandomValues(new Uint8Array(32));
    const uvZeroAuthData = await buildAuthenticatorData(rpId, 0x01, 7); // UV bit (0x04) missing!
    const clientDataJSON = new TextEncoder().encode(
      JSON.stringify({
        type: 'webauthn.get',
        challenge: bytesToBase64Url(challenge),
        origin,
      })
    );
    const khalidCreds = (await hasActiveBiometricForUser(khalidEmail)).credentials;
    const uvZeroCheck = await verifyWebAuthnAssertionCryptographically({
      assertion: {
        id: khalidKey.credentialIdB64Url,
        rawId: khalidKey.rawId.buffer,
        type: 'public-key',
        authenticatorAttachment: 'platform',
        getClientExtensionResults: () => ({}),
        toJSON: () => ({}),
        response: {
          authenticatorData: uvZeroAuthData.buffer,
          clientDataJSON: clientDataJSON.buffer,
          signature: new ArrayBuffer(64),
          userHandle: khalidKey.userHandle.buffer,
        } as AuthenticatorAssertionResponse,
      } as PublicKeyCredential,
      expectedChallenge: challenge,
      expectedOrigin: origin,
      expectedRpId: rpId,
      targetEmail: khalidEmail,
      allowedCredentialsForUser: khalidCreds,
    });
    expect(uvZeroCheck.verified).toBe(false);
    expect(uvZeroCheck.reasonAr).toContain('UV=0');

    // Attack 4: Cloned authenticator with non-increasing signCount (enrolled at signCount=5, asserts signCount=5)
    const clonedAuthData = await buildAuthenticatorData(rpId, 0x01 | 0x04, 5);
    const clientHash = new Uint8Array(await crypto.subtle.digest('SHA-256', clientDataJSON));
    const clonedPayload = new Uint8Array(clonedAuthData.length + clientHash.length);
    clonedPayload.set(clonedAuthData, 0);
    clonedPayload.set(clientHash, clonedAuthData.length);
    const validSigForCloned = p1363ToDerEcdsa(
      new Uint8Array(
        await crypto.subtle.sign(
          { name: 'ECDSA', hash: 'SHA-256' },
          khalidKey.keyPair.privateKey,
          clonedPayload
        )
      )
    );
    const cloneCheck = await verifyWebAuthnAssertionCryptographically({
      assertion: {
        id: khalidKey.credentialIdB64Url,
        rawId: khalidKey.rawId.buffer,
        type: 'public-key',
        authenticatorAttachment: 'platform',
        getClientExtensionResults: () => ({}),
        toJSON: () => ({}),
        response: {
          authenticatorData: clonedAuthData.buffer,
          clientDataJSON: clientDataJSON.buffer,
          signature: validSigForCloned.buffer,
          userHandle: khalidKey.userHandle.buffer,
        } as AuthenticatorAssertionResponse,
      } as PublicKeyCredential,
      expectedChallenge: challenge,
      expectedOrigin: origin,
      expectedRpId: rpId,
      targetEmail: khalidEmail,
      allowedCredentialsForUser: khalidCreds,
    });
    expect(cloneCheck.verified).toBe(false);
    expect(cloneCheck.reasonAr).toContain('عداد التوقيع');
  });
});
